contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount, bool doWithdraw) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        // Deposit funds (state-changing call must be top-level)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        // Record balances before potential withdraw
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        // Attempt withdrawAll if requested; top-level state-changing call
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // Record balances after first withdraw attempt
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        // Attempt a second withdraw to observe whether any additional funds are transferred
        bool reverted2;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }
        uint afterC2 = address(c).balance;
        uint afterThis2 = address(this).balance;
        // Single assert expressing the invariant for all inputs
        assert(
            // If we didn't attempt withdraw, nothing about withdraw behavior is required; require doWithdraw==true to reason about withdraws
            (!doWithdraw) ||
            // If we did attempt withdraw:
            (doWithdraw && (
                // Either the first withdraw reverted
                reverted
                // Or it succeeded and the change in c's balance equals the gain of this contract, and the second withdraw transfers no additional funds
                || (
                    !reverted
                    && (beforeC - afterC) == (afterThis - beforeThis)
                    && (afterC - afterC2) == 0
                    && (afterThis2 - afterThis) == 0
                )
            ))
        );
    }
    receive() external payable {}
}

