pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, bool doWithdraw) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint afterC2 = address(c).balance;
        uint afterThis2 = address(this).balance;
        assertTrue((!doWithdraw) ||
            // If we did attempt withdraw:
            (doWithdraw && (
                // Either the first withdraw reverted
                reverted
                // Or it succeeded and the change in c's balance equals the gain of this contract, and the second withdraw transfers no additional funds
                || (
                    !reverted
                    && (beforeC - afterC) == (afterThis - beforeThis)
                    && (afterC - afterC2) == 0
                    && (afterThis2 - afterThis) == 0
                )
            )));
    }

    function testFuzz_run(uint256 depositAmount, bool doWithdraw) public {
        _run(depositAmount, doWithdraw);
    }

    receive() external payable {}
}
